contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(
        address baseToken_,
        address nft_,
        uint128 virtualBaseTokenReserves_,
        uint128 virtualNftReserves_,
        uint56 changeFee_,
        uint16 feeRate_,
        bytes32 merkleRoot_,
        bool useStolenNftOracle_,
        bool payRoyalties_
    ) public {
        require(feeRate_ <= 5000, "feeRate too high");
        require(!c.initialized(), "already initialized");

        c.initialize(
            baseToken_,
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        ); if (__ESBMC_reverted()) return;

        assert(c.baseToken() == baseToken_);
    }
}

