// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(address baseToken_, address nft_, uint128 virtualBaseTokenReserves_, uint128 virtualNftReserves_, uint56 changeFee_, uint16 feeRate_, bytes32 merkleRoot_, bool useStolenNftOracle_, bool payRoyalties_) internal {
        feeRate_ = uint16(bound(uint256(feeRate_), 0, 5000));
        vm.assume(!c.initialized());
        try c.initialize(
            baseToken_,
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        ) {} catch { return; }
        assertTrue(c.baseToken() == baseToken_);
    }

    function testFuzz_run(address baseToken_, address nft_, uint128 virtualBaseTokenReserves_, uint128 virtualNftReserves_, uint56 changeFee_, uint16 feeRate_, bytes32 merkleRoot_, bool useStolenNftOracle_, bool payRoyalties_) public {
        vm.assume(baseToken_.code.length == 0 && uint160(baseToken_) > 0xffff && baseToken_ != address(this) && baseToken_ != address(c) && baseToken_ != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && baseToken_ != 0x000000000000000000636F6e736F6c652e6c6f67 && baseToken_ != 0x4e59b44847b379578588920cA78FbF26c0B4956C && baseToken_ != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(nft_.code.length == 0 && uint160(nft_) > 0xffff && nft_ != address(this) && nft_ != address(c) && nft_ != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && nft_ != 0x000000000000000000636F6e736F6c652e6c6f67 && nft_ != 0x4e59b44847b379578588920cA78FbF26c0B4956C && nft_ != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(baseToken_, nft_, virtualBaseTokenReserves_, virtualNftReserves_, changeFee_, feeRate_, merkleRoot_, useStolenNftOracle_, payRoyalties_);
    }

    receive() external payable {}
}
